-- ABFM Training content refresh (Nov 2026): new categories, learning paths, toolbox talks and channels.
-- Run once in the Supabase SQL editor. Video ids below are the ids already in the library.
begin;

-- ---------- 1. Categories ----------
update public.docs set version = version + 1, updated_at = now(), updated_by = 'content refresh',
content = jsonb_set(content, '{categories}', $j$[
 {"name":"Health & Safety","icon":"🦺","keywords":["safety","ppe","lockout","tagout","loto","ladder","harness","fall protection","working at height","confined space","heat stress","heat illness","first aid","manual handling","hazard","permit to work","risk assessment","near miss","scaffold","toolbox talk"]},
 {"name":"HVAC & Chillers","icon":"❄️","keywords":["hvac","air condition","a/c","split ac","chiller","ahu","air handler","fcu","fan coil","vrf","vrv","package unit","refrigerant","refrigeration","compressor","condenser","evaporator","cooling tower","superheat","subcool","r410","r32","r22","brazing","flare","district cooling","heat exchanger","thermostat"]},
 {"name":"Electrical","icon":"⚡","keywords":["electrical","electrician","wiring","cable","breaker","mcb","mccb","rcd","rcbo","elcb","distribution board","socket","switch","lighting","led","contactor","motor","vfd","three phase","3 phase","earthing","megger","insulation resistance","generator","ats","multimeter","clamp meter"]},
