 {"name":"Kitchen & Laundry Appliances","icon":"🍳","keywords":["kitchen equipment","commercial kitchen","oven","fryer","cooker","dishwasher","ice machine","refrigerator","fridge","freezer","cold room","washing machine","dryer","laundry","microwave","appliance"]},
