-- ---------- 2. Move videos to the new categories ----------
update public.docs set version = version + 1, updated_at = now(), updated_by = 'content refresh',
content = jsonb_set(content, '{videos}', (
  select jsonb_agg(
    case
      when v->>'id' in ('hvac-KrrbmWSa1ug', 'hvac-912yUrU0Mw8') then jsonb_set(v, '{category}', '"Health & Safety"')
      when m.new is not null then jsonb_set(v, '{category}', to_jsonb(m.new))
      else v end
    order by ord)
  from jsonb_array_elements(content->'videos') with ordinality t(v, ord)
  left join (values ('HVAC', 'HVAC & Chillers'), ('Plumbing', 'Plumbing & Drainage'), ('Fire Systems', 'Fire & Life Safety'),
    ('Civil Jobs', 'Civil & Carpentry'), ('Water Tank Cleaning', 'Water Tanks & Pumps'), ('Duct Cleaning', 'Duct & Kitchen Exhaust'),
    ('Landscaping', 'Landscaping & Irrigation'), ('UAE Regulations', 'UAE Rules & Compliance')) m(old, new) on m.old = v->>'category'))
where name = 'videos';

-- ---------- 3. Channels: new category names + Gulf-focused channels ----------
