  left join (values ('HVAC', 'HVAC & Chillers'), ('Plumbing', 'Plumbing & Drainage'), ('Fire Systems', 'Fire & Life Safety'),
    ('Civil Jobs', 'Civil & Carpentry'), ('Duct Cleaning', 'Duct & Kitchen Exhaust'), ('Landscaping', 'Landscaping & Irrigation')) m(old, new) on m.old = c->>'category')
  || $j$[
   {"name":"MEP Tech Tips (Dubai)","url":"https://www.youtube.com/c/MEPTECHTIPS","category":"","active":true},
   {"name":"MEP Techniques (facility O&M)","url":"https://www.youtube.com/@MEPTechniqueprabhu","category":"","active":true},
