-- ---------- 4. Learning paths (replace) ----------
update public.docs set version = version + 1, updated_at = now(), updated_by = 'content refresh',
content = jsonb_build_object('assignments', coalesce(content->'assignments', '[]'::jsonb), 'paths', $j$[
 {"id":"safety-induction","icon":"🦺","title":"Safety Induction for Every Technician","description":"The must-know safety for everyone on site: isolation and lockout, heat stress, ladders and harnesses, fire extinguishers, PPE and safe driving.","videos":["healt-n1gWyBOn4OM","healt-CdFPlD3vQ20","healt-kuGqzVgPTso","healt-rOPiqAf-DlI","healt-SPpL4bu7Bng","healt-sWuOBu3GjHw","healt-seuWV6qTl4k","fires-GVBamXXVD30","hvac-912yUrU0Mw8","hvac-KrrbmWSa1ug"]},
 {"id":"split-ac-fcu","icon":"❄️","title":"Split AC and FCU Maintenance","description":"For new AC technicians: how the cooling cycle works, the parts of a split unit and FCU, routine service, filters and blocked drains.","videos":["hvac-101","hvac-102","hvac-rSnOG-oMC5w","hvac-104","hvac-15MXhGjXXhw","hvac-PdkasaHKP3c","hvac-103","hvac-MYi4EHtfCEE","hvac-WaICUTIW3og"]},
 {"id":"refrigerant-work","icon":"🧊","title":"Refrigerant Work: Install, Test, Charge","description":"Flaring and brazing, nitrogen leak testing, pulling a deep vacuum, recovering refrigerant and reading superheat and subcooling.","videos":["hvac-105","hvac-110","hvac-108","hvac-107","hvac-111","hvac-tbXKvnKZrYs"]},
 {"id":"hvac-fault-finding","icon":"🔧","title":"HVAC Fault Finding","description":"For experienced technicians: meter skills, blown fuses, compressors that won't start, expansion valves, restrictions and VRF systems.","videos":["hvac-RlW4P-zL81Q","hvac-kkLvyE_YJE8","hvac-kKVHfHLgVW0","hvac-112","hvac-ztzTNf3smr4","hvac-113","hvac-gFUrDX_ze-M","hvac-tQE1nGz3Ydg","hvac-109"]},
 {"id":"electrical-safety-testing","icon":"⚡","title":"Electrical Safety and Testing","description":"Isolating distribution boards safely, using a clamp meter, testing RCDs and ring circuits, insulation resistance and bathroom rules.","videos":["elect-Q-j9IsxKZog","elec-103","elec-109","elect-IElUDCQfTgg","elec-116","elect-X9gHO8AOllk","elect-Fg7lFCOJPm4"]},
 {"id":"motors-controls","icon":"⚙️","title":"Motors, Contactors and VFDs","description":"Three-phase power, contactors and overloads, start/stop circuits, VFDs and generator changeover (ATS).","videos":["elec-104","elect-EElZjxhQxHs","elec-107","elec-106","elec-108","elec-110","elec-112","elec-114","elec-111"]},
 {"id":"electrical-installation","icon":"🔌","title":"Electrical Installation Basics","description":"Stripping cable, wiring sockets and switches, conduit, cable tray and SWA glands, done neatly and to standard.","videos":["elect-GeLWlyNRWuk","elec-105","elect-3m0bOJL5Bjs","elect-pOfXina3uUQ","elect-nhcaeubedhs","elect-bj-qXukUy_8","elect--JRAv-7Xg68"]},
 {"id":"plumbing-service-calls","icon":"🚰","title":"Plumbing Service Calls","description":"The everyday jobs: dripping taps, cartridges, toilets and flush valves, traps, angle valves and finding hidden leaks.","videos":["plumb-101","plumb-102","plumb-104","plumb-103","plumb-106","plumb-105","plumb-109","plumb-107","plumb-115","plumb-110"]},
 {"id":"fire-life-safety","icon":"🧯","title":"Fire and Life Safety Basics","description":"Using an extinguisher, how detectors and fire alarm panels work, sprinkler types and the wet alarm valve.","videos":["fires-GVBamXXVD30","fires-SQDWNdO6xE4","fires-NIxWpqcj8t4","fires-nyBTkpNB0hU","fires-bym_AagItOc","fires-9urpPzmsxHo"]},
 {"id":"confined-space-tanks","icon":"💧","title":"Confined Spaces and Water Tanks","description":"Safe entry into tanks and pits, then cleaning, disinfecting and testing water storage tanks.","videos":["healt-_loONTyxmks","healt-aCvcvjyL01E","water-3ZwVOsB_vGs","water-jmdOfrL4zz0","water-M7qGBZX_GZo"]},
 {"id":"finishes-repairs","icon":"🎨","title":"Painting, Tiling and Repairs","description":"Clean painting without lap marks, caulking, drywall repairs, waterproofing wet areas and tiling.","videos":["paint-oWyQjMBQIik","paint--8gLPN1W_o0","civil-Fdy9uRvpI-E","civil-EVN_tUlynHU","paint-rwfmx5cCWdE","civil-PpRb6lWX44o","civil-3M8oj9zh3Uo"]},
 {"id":"irrigation","icon":"🌴","title":"Irrigation and Landscaping","description":"Controllers and timers, valves, low pressure, sprinkler heads and drip lines.","videos":["lands-xrGuelmdIQI","lands-qoBe4nTrVz0","lands-jCowCVTR6VE","lands-s8XagZQ9Suk","lands-XmQR2emG9D4","lands-QvTpFOz1GTQ","lands-t_dSruoWQIw"]},
 {"id":"duct-air-quality","icon":"🌀","title":"Duct Cleaning and Indoor Air","description":"Cleaning ducts and coils the right way, filters and keeping air flowing well.","videos":["ductc-5N-1DIz4amg","ductc-iVQVXkH_MAo","ductc-J0NFvScegbk","hvac-PdkasaHKP3c","hvac-CqM2TkvT2-U"]}
