-- ---------- 5. Toolbox talks (replace) ----------
update public.docs set version = version + 1, updated_at = now(), updated_by = 'content refresh',
content = jsonb_build_object('talks', $j$[
 {"id":"heat-midday-break","icon":"☀️","title":"Heat stress and the midday break","video":"healt-kuGqzVgPTso","points":["From 15 June to 15 September, outdoor work in direct sun stops between 12:30 and 15:00 (the UAE midday break).","Drink water every 15–20 minutes, even if you are not thirsty. Energy drinks do not help.","Rest in the shade or a cool room, and slow down in the hottest hours.","Headache, dizziness, confusion or no sweating are danger signs: stop, cool down and tell your supervisor.","Watch your partner. People with heat stroke often don't notice it themselves."],"ask":"Where is the nearest shade and cold drinking water on today's site?"},
 {"id":"prove-dead","icon":"🔌","title":"Prove dead before you touch","video":"elect-Q-j9IsxKZog","points":["Never trust a label, a switch position or someone saying \"it's off\".","Isolate, lock and tag, then test every conductor with an approved voltage tester.","Check your tester on a known live source before and after the test.","Only qualified electricians work on electrical panels and wiring.","If anything is not clear, stop and ask your supervisor."],"ask":"Who on this team has an approved voltage tester today, and has it been checked?"},
 {"id":"lockout-tagout","icon":"🔒","title":"Lockout and tagout, every time","video":"healt-CdFPlD3vQ20","points":["Before working on any machine, pump, AHU or panel, switch it off and isolate every energy source.","Put your own lock and tag on the isolator. One person, one lock, one key.","Try to start it to prove it is safe before you begin.","Never remove someone else's lock.","Remove your lock only when the job is finished and everyone is clear."],"ask":"Which equipment today needs more than one isolation point?"},
 {"id":"ladders","icon":"🪜","title":"Ladders and stepladders","video":"healt-SPpL4bu7Bng","points":["Check the ladder before every use: feet, rungs, locks and labels.","Set it on firm, level ground and lock the stepladder fully open.","Keep three points of contact and never stand on the top two steps.","Don't overreach. Climb down and move the ladder instead.","Damaged ladders are tagged and taken out of use, not repaired on site."],"ask":"Is every ladder in our van in good condition today?"},
 {"id":"work-at-height","icon":"🧗","title":"Working at height","video":"healt-seuWV6qTl4k","points":["Any work where you could fall and get hurt is work at height, including roofs, platforms and tall ladders.","Use guardrails or a scaffold first; a harness is the last line of protection.","Inspect your harness and lanyard before use and clip to a rated anchor point.","Only use scaffolds with a green tag.","Keep tools tied or in a bag so nothing falls on people below."],"ask":"Where on our sites is there a fall risk we haven't fixed yet?"},
 {"id":"confined-space","icon":"🕳️","title":"Confined spaces: tanks, pits and manholes","video":"healt-_loONTyxmks","points":["Never enter a tank, pit, manhole or duct without a permit.","The air is tested before entry and checked while you work.","A trained standby person stays at the entrance the whole time.","Ventilate the space and wear the right breathing protection.","If someone collapses inside, do not go in after them. Raise the alarm."],"ask":"Who is our trained standby person for the next tank job?"},
 {"id":"hot-work","icon":"🔥","title":"Hot work: brazing, welding and grinding","video":"hvac-110","points":["Hot work needs a permit before you start.","Clear anything that can burn, or cover it with a fire blanket.","Keep a suitable fire extinguisher within reach.","Purge with nitrogen when brazing refrigerant pipe.","Check the area again 30 minutes after you finish for hidden smouldering."],"ask":"Where is the nearest fire extinguisher to today's hot work?"},
 {"id":"refrigerant","icon":"🧊","title":"Handling refrigerant safely","video":"hvac-111","points":["Liquid refrigerant can freeze skin and eyes in seconds. Wear gloves and goggles.","Never vent refrigerant into the air. Recover it into a proper cylinder.","Work in a ventilated area. Refrigerant can push out oxygen in small rooms.","Keep cylinders upright, secured and away from heat and direct sun.","Never heat a cylinder with a flame to speed up charging."],"ask":"Is our recovery cylinder labelled and below its maximum fill?"},
 {"id":"chemicals","icon":"🧪","title":"Chemicals: read the label, never mix","points":["Read the label and safety data sheet before using any chemical.","Never mix chemicals. Bleach with acid or ammonia makes toxic gas.","Dilute exactly as instructed: more is not better.","Wear gloves and goggles, and keep the area ventilated.","Keep chemicals in labelled original containers, never in water bottles."],"ask":"Which chemicals do we use most, and where are their safety data sheets?"},
 {"id":"manual-handling","icon":"📦","title":"Lifting and carrying","points":["Check the weight first. If it's heavy or awkward, get help or a trolley.","Bend your knees, keep your back straight and the load close.","Don't twist while lifting. Turn with your feet.","Clear the route before you carry anything.","Report back pain early. Don't wait until it gets worse."],"ask":"What is the heaviest thing we move regularly, and how do we move it?"},
 {"id":"ppe","icon":"🥽","title":"The right PPE for the job","points":["Safety shoes and work clothes are the minimum on every site.","Add glasses, gloves, ear protection, hard hat or mask as the job needs.","Check PPE before use and replace anything damaged.","PPE only works if it fits and you wear it the whole time.","If you don't have the right PPE, don't start the job. Ask for it."],"ask":"Is anyone missing PPE they need for today's jobs?"},
 {"id":"tools","icon":"🛠️","title":"Hand and power tool checks","points":["Check tools and cables before use: no cracks, cuts or loose parts.","Keep guards on grinders and saws. Never remove them.","Unplug before changing blades, bits or discs.","Use the right tool for the job, not the nearest one.","Tag damaged tools and hand them in."],"ask":"Which tool in our kit needs replacing?"},
 {"id":"slips-trips","icon":"🧹","title":"Slips, trips and good housekeeping","points":["Put out wet-floor signs whenever a floor is wet.","Keep cables, hoses and tools out of walkways.","Clean as you go, not only at the end of the job.","Report loose tiles, broken steps and poor lighting.","In occupied buildings, leave the area cleaner than you found it."],"ask":"Where do people trip or slip most on our sites?"},
 {"id":"fire-extinguisher","icon":"🧯","title":"Using a fire extinguisher","video":"fires-GVBamXXVD30","points":["Raise the alarm first, then call 997 (Civil Defence) if needed.","Only fight a small fire, and only with a clear way out behind you.","Remember PASS: Pull the pin, Aim at the base, Squeeze, Sweep.","Use CO2 on electrical fires. Never use water on electrical equipment.","If the fire grows, leave, close the door and go to the assembly point."],"ask":"Where is the assembly point for the building we're in today?"},
 {"id":"emergency-numbers","icon":"📞","title":"Emergencies: who to call","points":["In the UAE: 999 police, 998 ambulance, 997 Civil Defence (fire).","Know the site emergency number and the nearest first aider.","Give your exact location: building, floor and nearest landmark.","Send someone to meet the ambulance at the entrance.","Report every emergency to your supervisor as soon as it is safe."],"ask":"What is the exact address of the site we're on today?"},
 {"id":"first-aid","icon":"⛑️","title":"First aid basics on site","points":["Know who the first aiders are and where the first aid kit is.","Don't move someone who has fallen unless they are in danger.","Cool burns under clean running water for 20 minutes.","Press firmly on bleeding wounds with a clean cloth.","Report every injury, even a small cut, so it's recorded."],"ask":"When did we last check the first aid kit in our van?"},
 {"id":"safe-driving","icon":"🚐","title":"Driving safely between sites","video":"hvac-912yUrU0Mw8","points":["Everyone wears a seatbelt, front and back, on every trip.","No phone while driving, not even at red lights.","Keep to speed limits and leave a safe distance.","Secure ladders, tools and gas cylinders so they can't move.","If you feel sleepy, stop somewhere safe and rest."],"ask":"Is everything in our van secured for today's drive?"},
 {"id":"ramadan-fasting","icon":"🌙","title":"Working safely while fasting","points":["Plan heavy and hot work for early in the shift.","Fasting in the heat raises the risk of dizziness and heat illness. Know the signs.","Take short rest breaks in the shade and don't rush.","Hydrate well between iftar and suhoor.","If you feel unwell, stop and tell your supervisor. That is not weakness, it's safety."],"ask":"Which jobs can we move earlier in the day during Ramadan?"},
 {"id":"dust-wind","icon":"🌪️","title":"Dust storms and high winds","points":["Stop roof, ladder and lifting work when the wind is strong.","Secure loose sheets, panels and materials so they can't blow away.","Wear glasses and a dust mask in dusty conditions.","Drive slowly with headlights on when visibility is low.","Check outdoor units and roofs for damage after a storm."],"ask":"What on our rooftops could blow away in strong wind?"},
 {"id":"near-miss","icon":"📝","title":"Report near misses","points":["A near miss is something that almost caused harm.","Reporting it helps stop the next one becoming an injury.","Report it the same day to your supervisor.","Say what happened and what could fix it.","Nobody is blamed for reporting honestly."],"ask":"Has anyone had a near miss this week?"},
 {"id":"occupied-buildings","icon":"🏢","title":"Working in occupied buildings and homes","points":["Wear your ID and introduce yourself before you start.","Protect floors and furniture, and barricade your work area.","Respect privacy: knock, wait, and never enter rooms you don't need to.","Keep noise and dust low, and tell residents before switching off water or power.","Clean up and explain what you did before you leave."],"ask":"How do we let residents know before we cut water or power?"},
 {"id":"water-hygiene","icon":"💧","title":"Water tanks and legionella","video":"water-M7qGBZX_GZo","points":["Legionella bacteria grow in warm, still water, like tanks, cooling towers and unused pipes.","Keep tank lids closed and vents screened.","Flush outlets that are rarely used, such as empty-room showers.","Clean and disinfect tanks on the schedule set by the municipality and your supervisor.","Report dirty tanks, missing lids or bad smells straight away."],"ask":"Which of our buildings have outlets that are rarely used?"},
 {"id":"portable-electrical","icon":"🔋","title":"Extension leads and portable equipment","points":["Check plugs and cables before use. No tape repairs.","Don't plug extension leads into extension leads.","Use an RCD-protected supply, especially outdoors or in wet areas.","Keep cables away from water, sharp edges and doors.","Unroll cable reels fully so they don't overheat."],"ask":"Is every extension lead in our van in good condition?"},
 {"id":"gas-cylinders","icon":"🛢️","title":"Gas cylinders","points":["Store and carry cylinders upright and chained or strapped.","Keep the valve cap on when not in use.","Never let oil or grease touch oxygen fittings.","Use flashback arrestors on oxy-fuel sets.","Store cylinders in a ventilated area, away from heat and sun."],"ask":"How are cylinders secured in our vans and stores?"},
 {"id":"hearing","icon":"🎧","title":"Protect your hearing","points":["Plant rooms, grinders and generators can damage hearing for life.","If you must shout to be heard, wear ear protection.","Fit foam earplugs properly: roll, insert, hold.","Keep exposure short in very noisy areas.","Ringing in your ears after work is a warning sign."],"ask":"Which of our plant rooms are noisy enough to need ear protection?"},
 {"id":"eyes","icon":"👓","title":"Protect your eyes","points":["Wear safety glasses when drilling, grinding, cutting or using chemicals.","Use goggles, not glasses, for splashes and refrigerant.","Know where the nearest eyewash is.","For a chemical splash, rinse with clean water for at least 15 minutes.","Never rub your eye if something is in it. Get first aid."],"ask":"Where is the nearest eyewash on today's site?"},
 {"id":"permit-to-work","icon":"📄","title":"Permit to work: why it matters","points":["High-risk jobs need a permit: hot work, confined space, height, electrical isolation.","The permit makes sure the risks are checked and controlled before you start.","Read the permit and follow every condition on it.","If the job or conditions change, stop and get the permit updated.","Close the permit properly when the job is done."],"ask":"Which of this week's jobs need a permit?"},
 {"id":"fatigue","icon":"😴","title":"Fatigue and night shifts","points":["Tiredness causes mistakes, as dangerous as working drunk.","Get proper sleep before a night shift.","Take your breaks, drink water and keep moving.","Avoid high-risk tasks when you feel very tired.","Tell your supervisor if you're too tired to work safely."],"ask":"How can we plan night jobs so the riskiest tasks happen early?"},
 {"id":"rooftop-plant","icon":"🏙️","title":"Rooftops and plant areas","points":["Tell someone before you go on a roof or into a plant room.","Stay away from roof edges and fragile skylights.","Isolate fans and machinery before you reach into them.","Watch for hot pipes, sharp edges and slippery surfaces.","In summer, plan rooftop work for the cooler hours."],"ask":"Which rooftops we work on have unprotected edges?"},
 {"id":"stop-work","icon":"✋","title":"Everyone can stop unsafe work","points":["If something looks unsafe, you have the right and duty to stop the job.","Stopping work is never a reason for blame.","Tell the people involved and your supervisor what you saw.","Work starts again only when the risk is fixed.","Saying stop could save a life, maybe your own."],"ask":"Has anyone stopped a job this month? What happened?"}
]$j$::jsonb)
where name = 'toolbox';

-- ---------- 6. Staff trades: new category names ----------
update public.staff set trade = case trade
  when 'HVAC' then 'HVAC & Chillers' when 'Plumbing' then 'Plumbing & Drainage' when 'Civil Jobs' then 'Civil & Carpentry'
  when 'Duct Cleaning' then 'Duct & Kitchen Exhaust' when 'Fire Systems' then 'Fire & Life Safety' else trade end
where trade in ('HVAC', 'Plumbing', 'Civil Jobs', 'Duct Cleaning', 'Fire Systems');
update public.staff set trade = 'Cleaning & Housekeeping' where hr in ('6276','5895','6186','5858','5847','6356','6450','6142','5853','5877','6138','5860','6357','6452','5852','6322','6137','5903','6354','5851');
update public.staff set trade = 'Kitchen & Laundry Appliances' where hr in ('5477','6185','6404');
update public.staff set trade = 'BMS & Controls' where hr in ('6246','4977','6464','6290');

commit;
